        assert_eq!(order, signatures.map(Some));
    }

    /// The fields that identify a ranked block and its position, for comparing whole outputs.
    fn positions(ranked: &[RankedBlock]) -> Vec<(String, usize, usize, f64, usize)> {
        ranked
